const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Taklamakan Desert region
  const taklamakan = ee.Geometry.Polygon([
    [[81.0, 37.5], [87.0, 37.5], [87.0, 41.0], [81.0, 41.0], [81.0, 37.5]]
  ]);

  // 2. Load MODIS Aerosol Optical Depth data
  const aod2019 = ee.ImageCollection('MODIS/006/MCD19A2_GRANULES')
    .filterDate('2019-02-01', '2019-03-01')
    .filterBounds(taklamakan)
    .select('Optical_Depth_047');

  const aod2020 = ee.ImageCollection('MODIS/006/MCD19A2_GRANULES')
    .filterDate('2020-02-01', '2020-03-01')
    .filterBounds(taklamakan)
    .select('Optical_Depth_047');

  const size2019 = aod2019.size().getInfo();
  const size2020 = aod2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log('Empty collection for one or both periods');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate mean AOD for each period (scale factor 0.001)
  const mean2019_img = aod2019.mean().multiply(0.001);
  const mean2020_img = aod2020.mean().multiply(0.001);

  // 4. Check pixel counts
  const count2019 = mean2019_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: taklamakan,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_047').getInfo();

  const count2020 = mean2020_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: taklamakan,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_047').getInfo();

  console.log(`2019 Valid Pixels: ${count2019}`);
  console.log(`2020 Valid Pixels: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean AOD values
  const aod2019_val = mean2019_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: taklamakan,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_047').getInfo();

  const aod2020_val = mean2020_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: taklamakan,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_047').getInfo();

  console.log(`2019 Mean AOD: ${aod2019_val}`);
  console.log(`2020 Mean AOD: ${aod2020_val}`);

  // 6. Validation and final answer
  if (aod2019_val === null || aod2020_val === null || 
      isNaN(aod2019_val) || isNaN(aod2020_val) ||
      aod2019_val < -1 || aod2019_val > 5 || 
      aod2020_val < -1 || aod2020_val > 5) {
    console.log('Invalid AOD values detected');
    console.log('<answer>C3</answer>');
    return;
  }

  if (aod2020_val > aod2019_val) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
